-- ************************************** CRM.CAMPAIGN
CREATE TABLE IF NOT EXISTS CRM.CAMPAIGN
(
 CAMPAIGN_ID   char(18) NOT NULL COMMENT 'Unique 18-character identifier for each campaign, serving as the primary key. Used to link campaigns with related records such as interactions, contacts, and performance metrics.',
 NAME          varchar(120) NOT NULL COMMENT 'The descriptive name of the campaign (e.g., Spring Sale, Customer Retention Drive, Holiday Promotion). Provides a human-readable identifier for campaign tracking and reporting.',
 TYPE          varchar(40) COMMENT 'Specifies the communication channel or type of campaign (e.g., Email, Social Media, Direct Mail, In-Store, Webinar). Helps classify and segment campaigns by their delivery method and target audience.',
 STATUS        varchar(20) COMMENT 'The current lifecycle status of the campaign (e.g., Active, Completed, Planned, On Hold, Archived). Indicates whether the campaign is currently running, in preparation, or concluded.',
 START_DATE    date COMMENT 'The official launch date when the campaign begins execution. Used to calculate campaign duration and for timeline-based reporting and analysis.',
 END_DATE      date COMMENT 'The official conclusion date when the campaign ends. Used to determine campaign duration and to identify completed or expiring campaigns.',
 BUDGETED_COST decimal(18,2) COMMENT 'The estimated financial budget allocated for the campaign in decimal format (up to 18 digits with 2 decimal places). Used for budget planning, ROI calculations, and cost control.',
 CREATED_DATE  date COMMENT 'The system-generated date when the campaign record was initially created. Provides an audit trail for record creation and historical tracking.',
 ADDRESS_1     string NOT NULL COMMENT 'Primary address field for campaign execution location or mailing address. Used to store the main physical location or mailing address associated with the campaign.',

 CONSTRAINT PK_CAMPAIGN PRIMARY KEY ( CAMPAIGN_ID )
)
COMMENT = 'Tracks marketing campaigns, including details about their type, duration, budget, and status. Maintains comprehensive campaign information to support marketing planning, execution, and performance analysis.';
